private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            sb.append((char) b);
        } else {
            int charLength = 2;
            if ((b & 0xE0) == 0xC0) {
                charLength = 2;
            } else if ((b & 0xF0) == 0xE0) {
                charLength = 3;
            } else if ((b & 0xF8) == 0xF0) {
                charLength = 4;
            } else {
                // Invalid UTF-8 sequence
                continue;
            }
            char c = (char) ((b & 0x1F) << ((charLength - 1) * 6));
            for (int j = 1; j < charLength; j++) {
                b = bb.get();
                if ((b & 0xC0) != 0x80) {
                    // Invalid UTF-8 sequence
                    continue;
                }
                c += (char) ((b & 0x3F) << ((charLength - j - 1) * 6));
            }
            sb.append(c);
        }
        i++;
    }
    return i;
}
