private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit()) {
        byte b = bb.get(i);
        if (b >= 0) {
            sb.append((char) b);
            i++;
        } else {
            if ((b & 0xE0) == 0xC0) {
                if (i + 1 < bb.limit()) {
                    sb.append((char) (((b & 0x1F) << 6) | (bb.get(i + 1) & 0x3F)));
                    i += 2;
                } else {
                    break;
                }
            } else if ((b & 0xF0) == 0xE0) {
                if (i + 2 < bb.limit()) {
                    sb.append((char) (((b & 0x0F) << 12) | ((bb.get(i + 1) & 0x3F) << 6) | (bb.get(i + 2) & 0x3F)));
                    i += 3;
                } else {
                    break;
                }
            } else if ((b & 0xF8) == 0xF0) {
                if (i + 3 < bb.limit()) {
                    char codePoint = (char) (((b & 0x07) << 18) | ((bb.get(i + 1) & 0x3F) << 12) | ((bb.get(i + 2) & 0x3F) << 6) | (bb.get(i + 3) & 0x3F));
                    if (codePoint <= 0xffff) {
                        sb.append((char) codePoint);
                    } else {
                        codePoint = (char) (((0xd800 - 0x10000) << 10) | (codePoint - 0x10000));
                        sb.append((char) codePoint);
                        codePoint = (char) (0xdc00 | (codePoint & 0x3ff));
                        sb.append((char) codePoint);
                    }
                    i += 4;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
    }
    return i;
}
