private void enlarge(final int size) {
    // Calculation of the new capacity needed
    int currentCapacity = this.capacity();
    int newCapacity = currentCapacity + size;

    // Creation of a new byte array with the new capacity
    byte[] newData = new byte[newCapacity];

    // Copying the old data to the new array
    System.arraycopy(this.data, 0, newData, 0, currentCapacity);

    // Updating the internal data reference and capacity
    this.data = newData;
    this.capacity = newCapacity;
}
