@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Determine the number of vertices in each part
    int part1Size = resultMap.size() / 2;
    int part2Size = resultMap.size() - part1Size;

    // Create vertices for each part
    for (int i = 0; i < part1Size; i++) {
        V vertex1 = resultMap.get("part1_" + i);
        target.addVertex(vertex1);
    }
    for (int i = 0; i < part2Size; i++) {
        V vertex2 = resultMap.get("part2_" + i);
        target.addVertex(vertex2);
    }

    // Connect vertices from different parts
    int index1 = 0;
    int index2 = part1Size;
    for (int i = 0; i < resultMap.size(); i++) {
        V vertex1 = resultMap.get("part1_" + index1);
        V vertex2 = resultMap.get("part2_" + index2);
        target.addEdge(vertex1, vertex2, null);
        index2++;
        if (index2 == resultMap.size()) {
            index1++;
            index2 = part1Size + index1;
        }
    }
}
