public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int length = schema.getByteSize(message);
    byte[] lengthBytes = CodedOutputStream.encodeZigZag32(length);
    if (buffer.total() < 5 || buffer.needed() < 5 + length) {
        int newBufferSize = Math.max(5, buffer.needed() + 5);
        buffer = new LinkedBuffer(newByteBuffer(newBufferSize), newBufferSize);
    }
    CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer);
    codedOut.writeRawBytes(lengthBytes, 0, lengthBytes.length);
    schema.writeTo(codedOut, message);
    codedOut.flush();
    out.write(buffer.buffer(), 0, buffer.offset());
    out.flush();
    buffer.clear();
    return 5 + length;
}
