public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    outputInt32(out, size);
    outputBytes(out, data, buffer);
    return size;
}

private static void outputInt32(OutputStream out, int value) throws IOException {
    out.write(value & 0xff);
    out.write((value >> 8) & 0xff);
    out.write((value >> 16) & 0xff);
    out.write((value >> 24) & 0xff);
}

private static void outputBytes(OutputStream out, byte[] bytes, LinkedBuffer buffer) throws IOException {
    int remaining = bytes.length;
    while (remaining > 0) {
        int n = Math.min(LinkedBuffer.DEFAULT_BUFFER_SIZE, remaining);
        buffer.append(bytes, bytes.length - remaining, n);
        out.write(buffer.getBuffer(), buffer.offset(), n);
        remaining -= n;
    }
}
