    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long duration = end - start;
        long fetchDataDuration = 1000L; // Assuming FETCH_DATA_DURATION is 1 second

        if (duration <= fetchDataDuration) {
            timeRanges.add(new TimeRange(start, end));
        } else {
            long remainingDuration = duration;
            long currentStart = start;

            while (remainingDuration > 0) {
                long chunkDuration = Math.min(remainingDuration, fetchDataDuration);
                long nextStart = currentStart + chunkDuration;
                timeRanges.add(new TimeRange(currentStart, Math.min(nextStart, end)));
                currentStart = nextStart;
                remainingDuration = end - currentStart;
            }
        }

        return timeRanges;
    }
```

