static long compressTimeBucket(long timeBucket, int dayStep) {
    String dateStr = String.format("%08d", timeBucket);
    long year = Long.parseLong(dateStr.substring(0, 4));
    long month = Long.parseLong(dateStr.substring(4, 6));
    long day = Long.parseLong(dateStr.substring(6, 8));

    if (dayStep == 1) {
        return timeBucket;
    } else if (dayStep == 11) {
        if (day < 2) {
            day = 1;
        } else {
            day = 1 + ((day - 2) / 7) * 7;
        }
    } else if (dayStep == 12) {
        if (day < 3) {
            day = 1;
        } else {
            day = 1 + ((day - 2) / 7) * 7 + 1;
        }
    } else if (dayStep == 13) {
        if (day < 5) {
            day = 1;
        } else {
            day = day - 3;
        }
    }

    return year * 10000 + month * 100 + day;
}
