private static String performSubstitution(String value, Properties props) {
    int startIndex = 0;
    while ((startIndex = value.indexOf("${", startIndex)) != -1) {
        int endIndex = value.indexOf("}", startIndex);
        if (endIndex == -1) {
            break;
        }
        String varName = value.substring(startIndex + 2, endIndex);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            value = value.substring(0, startIndex) + varValue + value.substring(endIndex + 1);
        }
        startIndex += varValue != null ? varValue.length() : 0;
    }
    return value;
}
