private static String performSubstitution(String value, Properties props) {
    StringBuilder sb = new StringBuilder();
    int startIndex = 0;
    while (startIndex < value.length()) {
        int dollarSignIndex = value.indexOf('$', startIndex);
        if (dollarSignIndex == -1) {
            sb.append(value.substring(startIndex));
            break;
        }
        sb.append(value, startIndex, dollarSignIndex);
        if (dollarSignIndex + 1 < value.length() && value.charAt(dollarSignIndex + 1) == '{') {
            int endIndex = value.indexOf('}', dollarSignIndex + 2);
            if (endIndex == -1) {
                break;
            }
            String propKey = value.substring(dollarSignIndex + 2, endIndex);
            String propValue = props.getProperty(propKey);
            if (propValue != null) {
                sb.append(propValue);
            }
            startIndex = endIndex + 1;
        } else {
            sb.append('$');
            startIndex = dollarSignIndex + 1;
        }
    }
    return sb.toString();
}
