public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    return performSubstitution(value, props);
}

private static String performSubstitution(String value, Properties props) {
    // Regex pattern to match ${key}
    String regex = "\\$\\{([^}]+)\\}";
    Pattern pattern = Pattern.compile(regex);
    Matcher matcher = pattern.matcher(value);

    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String innerKey = matcher.group(1);
        String innerValue = props.getProperty(innerKey);
        if (innerValue != null) {
            matcher.appendReplacement(sb, innerValue);
        } else {
            matcher.appendReplacement(sb, matcher.group(0));
        }
    }
    matcher.appendTail(sb);

    return sb.toString();
}
