import java.io.UnsupportedEncodingException;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.URLDecoder;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) throws URISyntaxException {
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }

    // Remove leading '/' if present
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    List<String> segments = Arrays.asList(path.split("/"));

    if (decode) {
        List<String> decodedSegments = new ArrayList<>();
        for (String segment : segments) {
            try {
                decodedSegments.add(URLDecoder.decode(segment, "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                throw new URISyntaxException(u.toString(), "Decoding path segment failed", e);
            }
        }
        segments = decodedSegments;
    }

    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    for (String segment : segments) {
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}

class PathSegmentImpl {
    private String segment;

    public PathSegmentImpl(String segment) {
        this.segment = segment;
    }

    public String getSegment() {
        return segment;
