private static final long[] VARINT_MASK = {
    0x7F, 0x3F, 0x1F, 0x0F, 0x07, 0x03, 0x01, 0x00
};

public long readRawVarint64() throws IOException {
    int part = in.read();
    if (part == -1) {
        throw new IOException("Unexpected end of stream");
    }
    long result = part & VARINT_MASK[0];
    int shiftBy = 7;
    for (int i = 0; i < 8; i++) {
        if ((part & 0x80) == 0) {
            return result;
        }
        part = in.read();
        if (part == -1) {
            throw new IOException("Unexpected end of stream");
        }
        result |= (long) (part & VARINT_MASK[i]) << shiftBy;
        shiftBy += 7;
    }
    throw new IOException("Varint too long");
}
```

