public static int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    if (capacity < 2) {
        capacity = 2;
    } else {
        if (capacity <= 1000) {
            capacity = ((11 * capacity) / 10);
        }
        int prime = findNextPrime(capacity);
        return prime;
    }
    return capacity;
}

private static int findNextPrime(int number) {
    while (!isPrime(number)) {
        number++;
    }
    return number;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}
