public static int nextPrime(int desiredCapacity) {
    int capacity = Math.max(desiredCapacity, 2);
    if (capacity < 1111) {
        while (!isPrime(capacity)) {
            capacity++;
        }
    } else {
        while (!isPrime(capacity)) {
            capacity = (int)(capacity * 1.11);
        }
        capacity = (int)(capacity - (capacity * 0.11));
    }
    return Math.max(capacity, desiredCapacity);
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    for (int i = 2; i <= Math.sqrt(number); i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}
