 * <p>Unescapes any Java literals found in the <code>String</code>. For example, it will turn a sequence of <code>'\'</code> and <code>'n'</code> into a newline character, unless the <code>'\'</code> is preceded by another <code>'\'</code>.</p>
 * @param str the <code>String</code> to unescape, may be null
 * @return a new unescaped <code>String</code>, <code>null</code> if null string input
 */
public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < str.length()) {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                sb.append('\n');
                i++; // Skip the next character as it's part of the escape sequence
            } else if (nextChar == 't') {
                sb.append('\t');
                i++;
            } else if (nextChar == 'b') {
                sb.append('\b');
                i++;
            } else if (nextChar == 'r') {
                sb.append('\r');
                i++;
            } else if (nextChar == 'f') {
                sb.append('\f');
                i++;
            } else if (nextChar == '\"') {
                sb.append('"');
                i++;
            } else if (nextChar == '\'') {
                sb.append('\'');
                i++;
            } else if (nextChar == '\\') {
                sb.append('\\');
                i++;
            } else {
                sb.append('\\').append(nextChar);
                i++;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
