final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int index = constantPoolEntryIndex * 4 + 2; // Each entry is 4 bytes plus 2 for the tag and length
    int length = classFileBuffer[index++] & 0xFF; // Length of the UTF-8 string

    if (length > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer is too small");
    }

    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) ((classFileBuffer[index++] << 8) | (classFileBuffer[index++] & 0xFF));
    }

    return new String(charBuffer, 0, length);
}
