final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int offset = findUtf8EntryOffset(constantPoolEntryIndex);
    int length = readU2(offset);
    offset += 2;
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) readU1(offset++);
    }
    return new String(charBuffer, 0, length);
}

private int findUtf8EntryOffset(final int constantPoolEntryIndex) {
    int offset = 10; // Start after magic number and version
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = readU1(offset);
        offset += 1;
        if (tag == 1) {
            int length = readU2(offset);
            offset += 2 + length;
        } else {
            offset += 3; // skip 2 bytes for int or 1 byte for other
        }
    }
    return offset;
}

private int readU1(int offset) {
    return classFileBuffer[offset] & 0xFF;
}

private int readU2(int offset) {
    return ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
}
