public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength > 0) {
        if (byteArrayValue == null) {
            throw new IllegalArgumentException("byteArrayValue cannot be null if byteLength is greater than 0");
        }
        if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset is out of bounds");
        }
        if (byteLength > byteArrayValue.length - byteOffset) {
            throw new IllegalArgumentException("byteLength is out of bounds");
        }
        ensureCapacity(position + byteLength);
        System.arraycopy(byteArrayValue, byteOffset, byteArray, position, byteLength);
        position += byteLength;
    } else {
        ensureCapacity(position + byteLength);
        Arrays.fill(byteArray, position, position + byteLength, (byte) 0);
        position += byteLength;
    }
    return this;
}
