protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour.isEmpty()) {
        return graph.createPath();
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V startVertex = firstEdge.getSource();
    V endVertex = firstEdge.getTarget();
    GraphPath<V,E> path = graph.createPath(startVertex);

    while (iterator.hasNext()) {
        E edge = iterator.next();
        if (edge.getSource().equals(endVertex)) {
            path = graph.createPath(path, edge);
            endVertex = edge.getTarget();
        } else if (edge.getTarget().equals(endVertex)) {
            path = graph.createPath(path, graph.getEdge(endVertex, edge.getSource()));
            path = graph.createPath(path, edge);
            endVertex = edge.getSource();
        }
    }

    return path;
}
```

