        return input;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char nextChar = input.charAt(i + 1);
            if (nextChar == '\\' || nextChar == '.') {
                sb.append(nextChar);
                i++;
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
