private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.getPrev();
    ListNodeImpl<E> next = node.getNext();

    if (prev != null) {
        prev.setNext(next);
    } else {
        // If prev is null, then node is the first node in the list
        // Assuming there is a head pointer
        head = next;
    }

    if (next != null) {
        next.setPrev(prev);
    } else {
        // If next is null, then node is the last node in the list
        // Assuming there is a tail pointer
        tail = prev;
    }

    node.setPrev(null);
    node.setNext(null);

    size--;
    return true;
}
