/**
 * Remove the non null {@code node} from the list.
 */
private boolean unlink(ListNodeImpl<E> node) {
    if (node == null || !list.contains(node)) {
        return false;
    }

    // Get the previous and next nodes
    ListNodeImpl<E> prev = node.getPrev();
    ListNodeImpl<E> next = node.getNext();

    // Update the previous node's next reference
    if (prev != null) {
        prev.setNext(next);
    } else {
        // If prev is null, then node is the head of the list
        first = next;
    }

    // Update the next node's previous reference
    if (next != null) {
        next.setPrev(prev);
    } else {
        // If next is null, then node is the tail of the list
        last = prev;
    }

    // Clear the node pointers
    node.setPrev(null);
    node.setNext(null);

    // Decrement the size of the list
    size--;

    return true;
}
