private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    for (int i = 0; i < terminators.length; i++) {
        if (terminators[i] == '\0' || terminators[i] == '\n' || terminators[i] == '\r') {
            throw new IllegalArgumentException("Terminators array contains invalid character: " + terminators[i]);
        }
    }
    boolean done = false;
    while (!done) {
        int c = System.in.read();
        if (c == -1) {
            break;
        }
        char ch = (char) c;
        boolean isTerminator = false;
        for (int i = 0; i < terminators.length; i++) {
            if (ch == terminators[i]) {
                done = true;
                isTerminator = true;
                break;
            }
        }
        if (!done) {
            token.append(ch);
        } else if (!isTerminator) {
            token.append(ch);
            done = false;
        }
    }
    return token.toString();
}
