private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int size = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(size, 0));
    long totalSum = 0;

    for (int i = size - 1; i >= 0; i--) {
        long value = bounds.get(i);
        suffixSum.set(i, (i < size - 1) ? suffixSum.get(i + 1) + value : value);
        totalSum += value;
    }

    return new Pair<>(suffixSum, totalSum);
}
