private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>(bounds.size());
    long totalSum = 0;
    long sum = 0;

    for (int i = 0; i < bounds.size(); i++) {
        sum += bounds.get(i);
        if (i == 0) {
            suffixSumList.add(0);
        } else {
            suffixSumList.add(suffixSumList.get(suffixSumList.size() - 1) + bounds.get(i - 1));
        }
    }

    totalSum += sum;

    for (int i = 0; i < suffixSumList.size(); i++) {
        suffixSumList.set(i, totalSum - suffixSumList.get(i));
    }

    return new Pair<>(suffixSumList, totalSum);
}
