private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Graph<Integer, E> graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edgeSet()) {
        int u = edge.getSource();
        int v = edge.getTarget();

        List<Pair<Integer, Integer>> localSeparatorList = getLocalMinimalSeparators(graph, u, v);
        globalSeparatorList.add(new Pair<>(localSeparatorList, edge.getElement()));
    }

    return globalSeparatorList;
}

private List<Pair<Integer, Integer>> getLocalMinimalSeparators(Graph<Integer, E> graph, int u, int v) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();

    Set<Integer> neighborsU = new HashSet<>();
    Set<Integer> neighborsV = new HashSet<>();

    for (Edge<E> edge : graph.incidentEdges(u)) {
        if (!edge.getSource().equals(v) && !edge.getTarget().equals(v)) {
            neighborsU.add(edge.getOpposite(u));
        }
    }

    for (Edge<E> edge : graph.incidentEdges(v)) {
        if (!edge.getSource().equals(u) && !edge.getTarget().equals(u)) {
            neighborsV.add(edge.getOpposite(v));
        }
    }

    neighborsU.retainAll(neighborsV);

    for (Integer neighbor : neighborsU) {
        separators.add(new Pair<>(u, neighbor));
        separators.add(new Pair<>(v, neighbor));
    }

    return separators;
}
