    for (E edge : graph.getEdges()) {
        List<Pair<Integer, Integer>> edgeMinimalSeparators = getEdgeMinimalSeparators(graph, edge);
        globalSeparatorList.add(new Pair<>(edgeMinimalSeparators, edge));
