private List<Pair<Integer, Integer>> getEdgeMinimalSeparators(Graph<E> graph, E edge) {
    List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();

    // Get the vertices connected by the edge
    Integer vertex1 = graph.getEdgeVertices(edge).getKey();
    Integer vertex2 = graph.getEdgeVertices(edge).getValue();

    // Get the neighbors of the vertices
    List<Integer> neighbors1 = graph.getNeighbors(vertex1);
    List<Integer> neighbors2 = graph.getNeighbors(vertex2);

    // Find the intersection of neighbors (excluding the vertices themselves)
    for (Integer neighbor1 : neighbors1) {
        if (neighbor1 != vertex2 && neighbors2.contains(neighbor1)) {
            minimalSeparators.add(new Pair<>(neighbor1, vertex2));
        }
    }

    for (Integer neighbor2 : neighbors2) {
        if (neighbor2 != vertex1 && neighbors1.contains(neighbor2)) {
            minimalSeparators.add(new Pair<>(neighbor2, vertex1));
        }
    }

    return minimalSeparators;
}
