import java.util.*;

public class GraphSeparator {
    private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Map<Integer, List<Integer>> graph, Map<Integer, E> edges) {
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

        for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
            int u = entry.getKey();
            for (int v : entry.getValue()) {
                List<Pair<Integer, Integer>> separators = new ArrayList<>();

                if (u < v) {
                    separators = findMinimalSeparators(graph, u, v);
                } else {
                    separators = findMinimalSeparators(graph, v, u);
                }

                globalSeparatorList.add(new Pair<>(separators, edges.get(u <= v ? u : v)));
            }
        }

        return globalSeparatorList;
    }

    private List<Pair<Integer, Integer>> findMinimalSeparators(Map<Integer, List<Integer>> graph, int u, int v) {
        List<Pair<Integer, Integer>> separators = new ArrayList<>();
        List<Integer> neighborsU = graph.get(u);
        List<Integer> neighborsV = graph.get(v);

        for (int w : neighborsU) {
            if (w == v) continue;
            if (neighborsV.contains(w)) {
                List<Integer> separator = new ArrayList<>();
                separator.add(w);
                separators.add(new Pair<>(separator, w));
            }
        }

        return separators;
    }
}
