/**
 * Puts an int into this byte vector. The byte vector is automatically enlarged if necessary.
 * @param intValue an int.
 * @return this byte vector.
 */
public ByteVector putInt(final int intValue){
    // Convert the int to a byte array
    byte[] byteArray = new byte[4];
    byteArray[0] = (byte) ((intValue >> 24) & 0xFF);
    byteArray[1] = (byte) ((intValue >> 16) & 0xFF);
    byteArray[2] = (byte) ((intValue >> 8) & 0xFF);
    byteArray[3] = (byte) (intValue & 0xFF);

    // Add the byte array to the byte vector
    for (byte b : byteArray) {
        this.elements[this.count++] = b;
    }

    // Automatically enlarge the byte vector if necessary
    if (this.count >= this.capacity) {
        this.capacity = this.count * 2;
        this.elements = Arrays.copyOf(this.elements, this.capacity);
    }

    return this;
}
