import org.jgrapht.graph.SimpleGraph;

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty subgraph is trivially a clique
    }

    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue; // Skip self-comparison
            }
            if (!graph.containsEdge(v1, v2)) {
                return false; // If there is any edge missing, it's not a clique
            }
        }
    }
    return true; // All pairs of vertices are connected by an edge
}
