public int readTag() throws IOException {
    int firstByte = is.read();
    if (firstByte == -1) {
        return 0;  // EOF
    }
    int fieldNumber = (firstByte & 0x7F) >> 3;
    int wireType = firstByte & 0x07;
    if (wireType == 0) {
        return (fieldNumber << 3) | wireType;
    }
    // Handle wire types that span multiple bytes
    int value = 0;
    int shift = 0;
    while (true) {
        int b = is.read();
        if (b == -1) {
            throw new IOException("Unexpected EOF while reading field tag");
        }
        value |= (b & 0x7F) << shift;
        shift += 7;
        if ((b & 0x80) == 0) {
            break;
        }
    }
    return (fieldNumber << 3) | wireType;
}
